-- =============================================================================
-- Données PostgreSQL — migrées depuis clients.db (SQLite)
-- À exécuter APRÈS schema.sql, sur des tables vides.
-- Les ids d'origine sont conservés ; les séquences IDENTITY sont recalées à la fin.
-- =============================================================================

SET client_encoding = 'UTF8';

BEGIN;

-- customers : 1000 lignes

-- products : 78 lignes

-- documents : 2196 lignes

-- document_lines : 10795 lignes

-- Recalage des séquences IDENTITY sur le max(id) importé
SELECT setval(pg_get_serial_sequence('customers', 'id'), COALESCE((SELECT max(id) FROM customers), 1), (SELECT max(id) IS NOT NULL FROM customers));
SELECT setval(pg_get_serial_sequence('products', 'id'), COALESCE((SELECT max(id) FROM products), 1), (SELECT max(id) IS NOT NULL FROM products));
SELECT setval(pg_get_serial_sequence('documents', 'id'), COALESCE((SELECT max(id) FROM documents), 1), (SELECT max(id) IS NOT NULL FROM documents));
SELECT setval(pg_get_serial_sequence('document_lines', 'id'), COALESCE((SELECT max(id) FROM document_lines), 1), (SELECT max(id) IS NOT NULL FROM document_lines));

COMMIT;
